import React, { useEffect, useRef } from 'react';

export default function Barcode({ value, width = 1.8, height = 50 }) {
  const ref = useRef();
  useEffect(() => {
    if (!value || !ref.current) return;
    const protocol = process.env.REACT_APP_PROTOCOL || 'http';
    const host = process.env.REACT_APP_HOST
      ? `${protocol}://${process.env.REACT_APP_HOST}`
      : window.location.origin;
    const url = `${host}/scan/${value}`;

    import('jsbarcode').then(({ default: JsBarcode }) => {
      JsBarcode(ref.current, String(url), {
        format: 'CODE128', width, height,
        displayValue: true, text: String(value), fontSize: 12, margin: 4,
        lineColor: '#0d1b35', background: '#fff',
      });
    });
  }, [value, width, height]);
  return <svg ref={ref} style={{ display:'block', maxWidth:'100%' }} />;
}
